  desc "Code graph for review and AI assistants, with the Claude Code MCP bridge"
  homepage "https://github.com/astrona-io/codesynapse"
  license "Apache-2.0"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.5/codesynapse-darwin-arm64"
      sha256 "594a7cbf9420c5afa0d349270de10545f5baaab7c78cb9e43ac32de79234d530"
    end
    on_intel do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.5/codesynapse-darwin-amd64"
      sha256 "887eb4a94dad43192f50ecb172834f8117f15030ce3bfd23cc43dfa4168fefc6"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.5/codesynapse-linux-arm64"
      sha256 "30012068fc576be75ac8866ec7282ea7a79adbbd8bd25368b9d2112f6cb990aa"
    end
    on_intel do
      url "https://github.com/astrona-io/codesynapse/releases/download/v0.0.5/codesynapse-linux-amd64"
      sha256 "3512a843fd3a7474bac6a963e1478876d7e7431012ce6768b099c8fb0e52543f"
    end
  end

  def install
    # A bare download isn't executable yet, and codesynapse runs below to
    # generate its completions.
    binary = Dir["codesynapse-*"].first
    chmod 0755, binary
    bin.install binary => "codesynapse"
    generate_completions_from_executable(bin/"codesynapse", "completion")
  end

  def caveats
    <<~EOS
      Connect Claude Code with a personal key (Settings → API keys in the dashboard):
        CODESYNAPSE_MCP_TOKEN=csk_... codesynapse mcp install --only claude
      then open a new chat. The bridge follows `brew upgrade codesynapse`.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/codesynapse --version")
    assert_match "__start_codesynapse", (bash_completion/"codesynapse").read
    # The bridge refuses to start without a chat ID instead of inventing one.
    assert_match "no chat session", shell_output("#{bin}/codesynapse mcp bridge 2>&1", 1)
  end
end
